	bootstrapDesignCenterCRMBaseURL               = "https://cloudresourcemanager.googleapis.com/v1/"
	bootstrapDesignCenterDeployerAccountID        = "tf-bootstrap-dc-deployer"
	bootstrapDesignCenterConnectedAppTemplateID   = "tf-bootstrap-connected-app-template"
