// BootstrapDesignCenterApplicationServiceAccount ensures a service account
// that Application Design Center can deploy applications with exists in the
// bootstrapped project, and returns its resource name
// (projects/{project}/serviceAccounts/{email}).
//
// The API checks that both the caller and the Design Center service agent can
// act as an application's service account, so the service agent is granted
// roles/iam.serviceAccountUser on it. The API rejects default Compute Engine
// and App Engine service accounts, so a dedicated one is created.
func BootstrapDesignCenterApplicationServiceAccount(t *testing.T) string {
	t.Helper()

	project := BootstrapDesignCenterProject(t)
	// The Design Center service agent is provisioned when the bootstrap Space
	// is first created, and must exist before it can be granted a role.
	BootstrapDesignCenterSpace(t)
	email := fmt.Sprintf("%s@%s.iam.gserviceaccount.com", bootstrapDesignCenterDeployerAccountID, project)
	name := fmt.Sprintf("projects/%s/serviceAccounts/%s", project, email)
	return bootstrapDesignCenterOnce(t, name, name, func(config *transport_tpg.Config) string {
		_, err := designCenterBootstrapRequest(config, project, "GET", bootstrapDesignCenterIAMBaseURL+name, nil)
		if err != nil {
			if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
				t.Fatalf("Bootstrapping failed. Error getting service account %s: %s", name, err)
			}
			_, err = designCenterBootstrapRequest(config, project, "POST", fmt.Sprintf("%sprojects/%s/serviceAccounts", bootstrapDesignCenterIAMBaseURL, project), map[string]interface{}{
				"accountId": bootstrapDesignCenterDeployerAccountID,
				"serviceAccount": map[string]interface{}{
					"displayName": "Bootstrap Design Center deployer",
				},
			})
			if err != nil && !transport_tpg.IsGoogleApiErrorWithCode(err, 409) {
				t.Fatalf("Bootstrapping failed. Error creating service account %s: %s", name, err)
			}
		}

		res, err := designCenterBootstrapRequest(config, project, "GET", bootstrapDesignCenterCRMBaseURL+"projects/"+project, nil)
		if err != nil {
			t.Fatalf("Bootstrapping failed. Error getting project %s: %s", project, err)
		}
		projectNumber, _ := res["projectNumber"].(string)
		if projectNumber == "" {
			t.Fatalf("Bootstrapping failed. Project %s has no projectNumber: %v", project, res)
		}
		member := fmt.Sprintf("serviceAccount:service-%s@gcp-sa-designcenter.iam.gserviceaccount.com", projectNumber)
		if ensureDesignCenterServiceAccountIAMMember(t, config, project, name, bootstrapDesignCenterServiceAccountUserRole, member) {
			log.Printf("[DEBUG] Waiting %s for the %s grant to %s on %s to propagate", bootstrapDesignCenterIAMPropagationWait, bootstrapDesignCenterServiceAccountUserRole, member, name)
			time.Sleep(bootstrapDesignCenterIAMPropagationWait)
		}
		return name
	})
}

// ensureDesignCenterServiceAccountIAMMember grants role to member on the
// service account called name unless it already has it, and reports whether
// it changed the policy.
func ensureDesignCenterServiceAccountIAMMember(t *testing.T, config *transport_tpg.Config, project, name, role, member string) bool {
	t.Helper()

	// A new service account can briefly be missing from IAM reads.
	policy, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "POST",
		Project:   project,
		RawURL:    bootstrapDesignCenterIAMBaseURL + name + ":getIamPolicy",
		UserAgent: config.UserAgent,
		Body:      map[string]interface{}{},
		Timeout:   5 * time.Minute,
		ErrorRetryPredicates: []transport_tpg.RetryErrorPredicateFunc{
			isDesignCenterBootstrapRetryableError,
			func(err error) (bool, string) {
				if transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
					return true, "Waiting for the new service account to propagate"
				}
				return false, ""
			},
		},
	})
	if err != nil {
		t.Fatalf("Bootstrapping failed. Error getting the IAM policy of %s: %s", name, err)
	}
	bindings, _ := policy["bindings"].([]interface{})
	for _, b := range bindings {
		binding, _ := b.(map[string]interface{})
		if binding["role"] != role {
			continue
		}
		members, _ := binding["members"].([]interface{})
		for _, m := range members {
			if m == member {
				return false
			}
		}
	}
	policy["bindings"] = append(bindings, map[string]interface{}{
		"role":    role,
		"members": []interface{}{member},
	})
	if _, err := designCenterBootstrapRequest(config, project, "POST", bootstrapDesignCenterIAMBaseURL+name+":setIamPolicy", map[string]interface{}{"policy": policy}); err != nil {
		t.Fatalf("Bootstrapping failed. Error granting %s to %s on %s: %s", role, member, name, err)
	}
	return true
}

// BootstrapDesignCenterConnectedApplicationTemplateRevisionURI ensures an
// ApplicationTemplate with a source Component, a destination Component and a
// Connection between them exists inside the bootstrapped Space, commits it,
// and returns the full revision URI. Applications created from it have
// connection_configs.
//
// It uses its own ApplicationTemplate, because the shared one may already
// have a revision that was committed without a Connection.
func BootstrapDesignCenterConnectedApplicationTemplateRevisionURI(t *testing.T) string {
	t.Helper()

	project, space := bootstrapDesignCenterSpaceName(t)
	appTemplate := space + "/applicationTemplates/" + bootstrapDesignCenterConnectedAppTemplateID
	revision := appTemplate + "/revisions/r-1"
	return bootstrapDesignCenterOnce(t, revision, revision, func(config *transport_tpg.Config) string {
		_, err := designCenterBootstrapRequest(config, project, "GET", bootstrapDesignCenterBaseURL+revision, nil)
		if err == nil {
			return revision
		}
		if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
			t.Fatalf("Bootstrapping failed. Error getting Design Center application template revision %s: %s", revision, err)
		}

		ensureDesignCenterResource(t, config, project, appTemplate, "applicationTemplateId", false, map[string]interface{}{
			"displayName": "Bootstrap Connected Application Template",
			"description": "Bootstrapped for Terraform acceptance tests",
		})
		source := appTemplate + "/components/" + bootstrapDesignCenterComponentID
		destination := appTemplate + "/components/" + bootstrapDesignCenterDestComponentID
		ensureDesignCenterResource(t, config, project, source, "componentId", false, map[string]interface{}{
			"displayName":               "Bootstrap Source Component",
			"sharedTemplateRevisionUri": bootstrapDesignCenterCloudRunTemplateURI,
		})
		ensureDesignCenterResource(t, config, project, destination, "componentId", false, map[string]interface{}{
			"displayName":               "Bootstrap Destination Component",
			"sharedTemplateRevisionUri": bootstrapDesignCenterCloudSQLTemplateURI,
		})
		ensureDesignCenterResource(t, config, project, source+"/connections/"+bootstrapDesignCenterConnectedAppConnectionID, "connectionId", false, map[string]interface{}{
			"destinationComponentUri": destination,
		})

		res, err := designCenterBootstrapRequest(config, project, "POST", bootstrapDesignCenterBaseURL+appTemplate+":commit", map[string]interface{}{})
		if err != nil {
			t.Fatalf("Bootstrapping failed. Error committing Design Center application template %s: %s", appTemplate, err)
		}
		waitForDesignCenterBootstrapOperation(t, config, project, bootstrapDesignCenterBaseURL, res)
		if name, _ := res["name"].(string); strings.Contains(name, "/revisions/") {
			return name
		}
		return revision
	})
}

